import {IslandAudio,WordSpeaker,migrateAudioSettings} from './audio.mjs';
import {selectPool} from './engine.mjs';
import {BattleAction} from './battle.mjs';
import {MonsterPark} from './park.mjs';
import {RangerCloud} from './cloud.mjs';
import {RARITIES,UNLOCKS,CATCH_RATES,STAT_KEYS,monsterStats,quality,rosterSummary,migrateLegacy,reduceGame,canCatch,specialCost,encounterOdds} from './rpg.mjs';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true"><use href="#i-${name}"></use></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageOK=true;
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{storageOK=false;return fallback;}}
let settings={mode:'mixed',timed:false,seconds:25,course:'ALL',scope:'all',groupIds:[],sfx:true,music:true,musicVolume:.12,sfxVolume:.35,voiceVolume:1,...migrateAudioSettings(read('wordling-settings-v1',{}))};
function save(){try{localStorage.setItem('wordling-settings-v1',JSON.stringify(settings));if(guest)localStorage.setItem('wordling-guest-v2',JSON.stringify(state));}catch{storageOK=false;}}
let data,MONSTERS=[],cloud,state={profile:null,mission:null},alias='',guest=false,view='auth',park=null,parkPage=0,parkReturnView='home',parkWasPaused=false,paused=false,modalPaused=false,round=null,intent='attack',actionBusy=false,networkBusy=false,battleAction=null,remainingMs=0,lastTick=0,waitingForAudio=false,speaking=false,voiceToken=0,audioDeadline,timerId,warehouseFilter='All',warehousePage=0;
const sound=new IslandAudio(settings),speaker=new WordSpeaker(sound);
const species=id=>MONSTERS.find(m=>m.id===id),indexOf=id=>MONSTERS.findIndex(m=>m.id===id);
const sprite=(i,cls='')=>{const m=MONSTERS[i];if(!m)return '';const s=m.sprite,x=s.columns===1?0:(s.index%s.columns)/(s.columns-1)*100,y=s.rows===1?0:Math.floor(s.index/s.columns)/(s.rows-1)*100;return `<div class="monster dex-sprite ${cls}" role="img" aria-label="${esc(m.name)}" style="background-image:url('${s.file}');background-size:${s.columns*100}% ${s.rows*100}%;background-position:${x}% ${y}%;--species-color:${m.color}"></div>`;};
const badge=m=>`<span class="rarity rarity-${m.rarity.toLowerCase()}">${m.rarity}</span>`;
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>t.classList.remove('visible'),4500);}
function sfx(kind){sound.effect(kind);}
function stopPark(){park?.destroy();park=null;}
function header(gameHeader=false){return `<header class="${gameHeader?'game-header':''}"><button class="brand" data-action="home" aria-label="Wordling Island home"><span class="brand-icon">${icon('leaf')}</span><span class="brand-title">WORDLING<small>ISLAND · FIELD RANGERS</small></span></button><nav aria-label="Main menu"><button class="nav-button" data-action="warehouse">${icon('book')}Warehouse</button><button class="nav-button" data-action="park">${icon('park')}Team Park</button><button class="nav-button" data-action="leaderboard">${icon('star')}Ranks</button><button class="nav-button" data-action="sound-settings">${icon('music')}Audio</button><button class="nav-button" data-action="${gameHeader?'pause':'help'}">${icon(gameHeader?'pause':'sparkle')}${gameHeader?'Pause':'Guide'}</button><button class="nav-button account-chip" data-action="account">${esc(guest?'Guest':alias)}</button></nav></header>`;}
function teamOverview(){const p=state.profile;if(!p)return '';const sum=rosterSummary(p,MONSTERS),active=state.mission&&['question','result'].includes(state.mission.phase);return `<section class="team-overview"><div><strong>${esc(guest?'Guest ranger':alias)}</strong><small>${guest?'Local save · not ranked':'Cloud save · synced'} · ${sum.caught} caught · ${sum.unique}/100 species · ${sum.missions} missions</small></div><div class="team-preview">${p.team.map(id=>{const m=p.inventory.find(m=>m.id===id);return `<button data-action="warehouse" title="${esc(species(m.speciesId).name)} Lv.${m.level}">${sprite(indexOf(m.speciesId))}<small>Lv.${m.level}</small></button>`;}).join('')}</div>${active?'<button class="next-button" data-action="resume-mission">Resume mission</button>':''}</section>`;}
function modalHeading(title,description=''){return `<div class="modal-heading"><div><h2>${esc(title)}</h2>${description?`<p>${esc(description)}</p>`:''}</div><button class="close-button" data-action="close-modal" aria-label="Close">${icon('close')}</button></div>`;}
function openModal(content){stopBattleAction();if(view==='game'&&!paused){modalPaused=true;paused=true;stopSpeech();}else if(!modal.open)modalPaused=false;modal.innerHTML=content;if(!modal.open)modal.showModal();}
function stopSpeech(){voiceToken++;speaker.stop();speaking=false;clearTimeout(audioDeadline);$('.audio-button')?.classList.remove('speaking');}
function speak(word,{first=false}={}){
 stopSpeech();const token=voiceToken,current=round,isQuestion=view==='game'&&round?.phase==='question'&&!paused&&word===round.card.english;
 if(first&&isQuestion)waitingForAudio=true;
 const finish=()=>{if(token!==voiceToken)return;speaking=false;$('.audio-button')?.classList.remove('speaking');if(isQuestion&&round===current){waitingForAudio=false;lastTick=Date.now();}clearTimeout(audioDeadline);updateVoiceStatus();};
 speaker.play(word,{onstart:()=>{if(token!==voiceToken)return;speaking=true;$('.audio-button')?.classList.add('speaking');updateVoiceStatus('Playing American English…');},onend:finish,onerror:message=>{if(token!==voiceToken)return;finish();if(first&&isQuestion)waitingForAudio=true;toast(message);}}).catch(()=>{finish();if(first&&isQuestion)waitingForAudio=true;toast('Audio unavailable. Tap the speaker to retry. The timer is paused.');});
 audioDeadline=setTimeout(()=>{if(token===voiceToken&&first&&waitingForAudio){stopSpeech();toast('Tap the speaker to retry. The timer is paused.');}},20000);
}
function updateVoiceStatus(message){const el=$('#voice-status');if(el)el.textContent=message||(speaker.fallback?'Device American voice · Reload to retry recordings':speaker.manifest?'Jenny · Natural American English · All words loaded':'Loading American voice…');}
async function act(action){if(networkBusy)throw Error('Saving your last move. Please wait.');networkBusy=true;document.body.classList.add('saving');try{state=guest?reduceGame(state,action,data,MONSTERS):await cloud.action(action);save();return state;}catch(e){if(e.status===409){const r=await cloud.me();state=r.state;}throw e;}finally{networkBusy=false;document.body.classList.remove('saving');}}
function renderAuth(mode='login',message=''){
 stopPark();stopSpeech();clearInterval(timerId);view='auth';sound.setScene('home');app.innerHTML=`<main class="auth-page"><section class="auth-art"><div class="eyebrow">WORDLING ISLAND · RANGER NETWORK</div><h1>Your words.<br>Your monster team.</h1><div class="auth-creatures">${sprite(0)}${sprite(2)}${sprite(4)}</div><p>100 original monsters. Listen, battle, and build your team.</p><p>Natural American English · CET Weeks + FET Lessons</p></section><section class="auth-panel"><h2>${mode==='register'?'Create your ranger code':'Welcome back, ranger'}</h2><p>${mode==='register'?'Choose a code to appear on the leaderboard.':'Sign in to bring your team to any device.'}</p><div class="segments">${[['login','Sign in'],['register','New player']].map(([v,l])=>`<button class="segment ${mode===v?'active':''}" data-action="auth-mode" data-mode="${v}">${l}</button>`).join('')}</div><form id="account-form" data-mode="${mode}"><label>Player code<input name="alias" autocomplete="username" autocapitalize="none" spellcheck="false" required pattern="[A-Za-z0-9_-]{3,16}" minlength="3" maxlength="16" placeholder="Ranger123"></label><small>3–16 letters, numbers, _ or -. No real name needed.</small><label>Password<input type="password" name="password" autocomplete="${mode==='register'?'new-password':'current-password'}" required minlength="8" maxlength="64" placeholder="At least 8 characters"></label>${mode==='register'?'<label>Confirm password<input type="password" name="confirm" autocomplete="new-password" required minlength="8" maxlength="64"></label><p class="auth-disclosure">Your player code and collection totals appear on the public leaderboard. Your password and save stay private.</p>':''}<p id="auth-feedback" class="feedback" role="status">${esc(message)}</p><button class="start-button" type="submit">${mode==='register'?'Create player':'Sign in'}</button></form><button class="text-button" data-action="recover">Forgot password?</button><div class="guest-entry"><button class="secondary-button" data-action="guest">Play as guest</button><small>Saved on this device only · not ranked</small></div></section></main>`;
}
async function loginForm(form){const button=form.querySelector('button[type="submit"]');if(button.disabled)return;const values=new FormData(form),mode=form.dataset.mode;if(mode==='register'&&values.get('password')!==values.get('confirm')){$('#auth-feedback').textContent='The passwords do not match.';return;}button.disabled=true;$('#auth-feedback').textContent='Connecting to the ranger network…';try{const r=await cloud.auth(mode,values.get('alias'),values.get('password'));state=r.state;alias=r.alias;guest=false;form.reset();if(r.recoveryCode){openModal(modalHeading('Save your recovery code','Keep this code somewhere safe. You need it to reset a forgotten password.')+`<code class="recovery-code">${esc(r.recoveryCode)}</code><p>This code is shown once. Do not share it.</p><button class="next-button" data-action="recovery-done">I saved my code</button>`);}else enterProfile();}catch(e){$('#auth-feedback').textContent=e.message;button.disabled=false;}}
function enterProfile(){if(!state.profile)return showStarter();if(state.mission&&['question','result'].includes(state.mission.phase))renderHome();else renderHome();}
function showStarter(){view='starter';app.innerHTML=`${header()}<main class="starter-page"><div class="eyebrow">YOUR FIRST FIELD PARTNER</div><h1>Choose your teammate.</h1><p>A free Level 5 partner. It can battle right away!</p><div class="starter-grid">${['leaf','honey','water'].map(id=>{const m=species(id);return `<button class="starter-card" data-action="starter" data-id="${id}">${sprite(indexOf(id))}<h2>${m.name}</h2><span>${m.type}</span><p>${m.description}</p></button>`;}).join('')}</div><p>Your starter counts as owned. Caught totals grow through word battles.</p></main>`;}
function pool(){if(settings.scope==='custom'&&!settings.groupIds.length)return [];return selectPool(data,settings.course,settings.scope==='all'?[]:settings.groupIds);}
function courseName(){if(settings.scope==='all')return settings.course==='ALL'?'CET + FET All words':`${settings.course} All words`;return `${settings.course==='ALL'?'CET + FET':settings.course} · Selected ${settings.groupIds.length} units`;}
function setChoice(action,value,label,active,extra=''){return `<button type="button" class="segment ${active?'active':''}" data-action="${action}" data-value="${value}" aria-pressed="${active}" ${extra}>${label}</button>`;}
function selectedSummary(){if(settings.scope==='all')return settings.course==='ALL'?'All CET Weeks + All FET Lessons':settings.course==='CET'?'All CET Weeks':'All FET Lessons';const selected=data.groups.filter(g=>settings.groupIds.includes(g.id));return selected.slice(0,3).map(g=>`${g.course} ${g.label}`).join(', ')+(selected.length>3?`, total ${selected.length} units`:'')||'No units selected';}
function unitPickerMarkup(){const courses=settings.course==='ALL'?['CET','FET']:[settings.course];return `<div class="course-picker"><div class="unit-actions"><button class="text-button ${settings.scope==='all'?'all-selected':''}" data-action="all-units">${settings.scope==='all'?'✓ ':''}All units</button><button class="text-button" data-action="clear-units">Clear</button><span class="word-count">${pool().length} words</span></div>${courses.map(course=>`<section class="course-unit-panel" aria-label="${course==='CET'?'CET Week selection':'FET Lesson selection'}"><div class="unit-panel-heading"><strong>${course==='CET'?'CET · Choose Weeks':'FET · Choose Lessons'}</strong><span>Multi-select</span><button class="text-button" data-action="course-all" data-course="${course}">Select all ${course}</button></div><div class="visible-unit-grid">${data.groups.filter(g=>g.course===course).map(g=>`<button class="unit-option ${settings.scope==='custom'&&settings.groupIds.includes(g.id)?'selected':''}" data-action="unit" data-value="${g.id}" aria-label="${course} ${g.label}" aria-pressed="${settings.scope==='custom'&&settings.groupIds.includes(g.id)}" title="${esc(g.topic||g.label)}">${g.label}${g.is_review?'<small>Review</small>':''}</button>`).join('')}</div></section>`).join('')}<p class="selection-summary" role="status">${esc(selectedSummary())}</p></div>`;}
function renderHome(openUnits=false){stopPark();stopSpeech();view='home';sound.setScene('home');const groups=data.groups.filter(g=>settings.course==='ALL'||g.course===settings.course);const count=pool().length;app.innerHTML=`${header()}<main class="home">${teamOverview()}<div class="home-layout"><section class="home-copy"><div class="eyebrow">HEAR IT. LINK IT. CATCH IT.</div><h1>Hear the word.<br><span style="color:var(--green)">Build your team.</span></h1><p class="intro">Grab your Wordlink. Your mission starts now!<br>Hear the word. Send your beam. Build your team.</p><div class="setup">${!storageOK?'<div class="saved-warning">Saving is unavailable in this browser. You can still play. Use a regular browser window to keep your progress.</div>':''}<div class="setup-section"><div class="setup-label"><span class="step-num">1</span>Choose your mode</div><div class="segments">${setChoice('mode','choice',icon('sound')+'Listen & Pick',settings.mode==='choice')}${setChoice('mode','spell','Aa Spell It',settings.mode==='spell')}${setChoice('mode','mixed',icon('sparkle')+'Mixed',settings.mode==='mixed')}</div></div><div class="setup-section"><div class="setup-label"><span class="step-num">2</span>Choose your pace<span class="label-end">Find your pace</span></div><div class="time-line"><div class="segments">${setChoice('timed','false','∞ No timer',!settings.timed)}${setChoice('timed','true',icon('clock')+'Timed',settings.timed)}</div>${settings.timed?`<select class="small-select" id="seconds" aria-label="Seconds per word">${[15,25,40].map(n=>`<option value="${n}" ${settings.seconds===n?'selected':''}>Per word ${n} sec</option>`).join('')}</select>`:''}</div></div><div class="setup-section"><div class="setup-label"><span class="step-num">3</span>Choose your word course<span class="label-end">2026 FALL · G1</span></div><div class="course-segments">${[['ALL','CET + FET'],['CET','CET'],['FET','FET']].map(([value,label])=>`<button class="course-chip ${settings.course===value?'active':''}" data-action="course" data-value="${value}" aria-pressed="${settings.course===value}">${label}</button>`).join('')}</div>${unitPickerMarkup()}</div><button class="start-button" data-action="start" ${count<1?'disabled':''}><span>${icon('leaf')}Start mission</span>${icon('arrow')}</button><p class="setup-note">${count<1?'Choose at least one unit':`Mission pool: ${count} words · 5 monsters + 1 boss`}<br>Natural American English · Tap to enable audio</p></div></section><aside class="hero-column" aria-label="Meet the Wordling team"><div class="float-sticker">GEAR UP.<br>LINK UP!<span>READY FOR THE NEXT ENCOUNTER</span></div><div class="hero-scene"><div class="scene-top"><span class="dot"></span>FRONTIER RIDGE · RANGER OUTPOST</div>${sprite(0,'hero-monster')}${sprite(1,'hero-friend')}<span class="word-bubble">hello!</span><img class="hero-player" src="assets/ranger-v3.png" alt="Original field ranger with orange goggles, navy gear, and a laptop scanner"><div class="hero-caption"><span class="caption-icon">${icon('sparkle')}</span><div><strong>Your next teammate is out there.</strong><small>Every word powers your next move.</small></div></div></div><div class="hero-bottom"><span class="hero-feature">${icon('sound')}Listen & learn</span><span class="hero-feature">${icon('book')}Course words</span><span class="hero-feature">${icon('star')}Build your team</span></div></aside></div><footer class="island-line"><span><strong>Small words. Epic adventures.</strong> Every word makes your team stronger.</span><span class="footer-note">KCIS G1 · ${data.summary.unique_word_count} WORDS · MADE FOR LITTLE EXPLORERS</span></footer></main>`;}
function showSoundSettings(){openModal(modalHeading('Audio settings','Set music, effects, and voice levels separately.')+`<div class="audio-settings"><div class="voice-setting"><span class="voice-badge">US</span><div><strong>Jenny · Natural American English</strong><p>Clear American English at a natural pace.</p><small id="voice-status"></small></div><button class="secondary-button" data-action="preview-voice">${icon('sound')}Preview flower</button></div>${[['music','Adventure music','Original adventure score · Soft background mix','musicVolume'],['sfx','Sound effects','Beams, battle moves, letters, and team interactions','sfxVolume']].map(([key,label,note,volume])=>`<div class="audio-control"><div class="audio-control-top"><div><strong>${label}</strong><small>${note}</small></div><button class="audio-toggle ${settings[key]?'on':''}" data-action="toggle-audio" data-setting="${key}" aria-pressed="${settings[key]}" aria-label="${label} toggle">${settings[key]?'On':'Off'}</button></div><label class="volume-line" for="${volume}"><span>Volume</span><input id="${volume}" type="range" min="0" max="100" value="${Math.round(settings[volume]*100)}" data-volume="${volume}" aria-label="${label} volume"><output id="${volume}-value">${Math.round(settings[volume]*100)}%</output></label></div>`).join('')}<div class="audio-control"><label class="volume-line" for="voiceVolume"><span>Voice volume</span><input id="voiceVolume" type="range" min="15" max="100" value="${Math.round(settings.voiceVolume*100)}" data-volume="voiceVolume" aria-label="Voice volume"><output id="voiceVolume-value">${Math.round(settings.voiceVolume*100)}%</output></label></div><p class="audio-hint">Voice comes first: music fades out during speech and returns softly afterward. Effects also become quieter. Audio starts after your first tap; leaving the tab pauses it.</p></div>`);updateVoiceStatus();speaker.ready.then(()=>updateVoiceStatus());}
async function startGame(){if(!pool().length)return;if(state.mission&&['question','result'].includes(state.mission.phase)){toast('Resume your mission, or return to base first.');return;}stopBattleAction();stopSpeech();await act({type:'start',settings});sfx('start');paused=false;intent='attack';window.scrollTo(0,0);syncRound(true);}
function syncRound(newWord=false){const m=state.mission;if(!m)return renderHome();if(['complete','rescued'].includes(m.phase))return renderFinish();const q=m.question;const same=round?.id===q.id;round={id:q.id,card:data.cards.find(c=>c.id===q.cardId),mode:q.mode,phase:m.phase,options:q.options,letters:q.letters,selected:same?round.selected:[],message:'',assisted:same?round.assisted:false,result:m.result};if(!same||newWord){remainingMs=m.settings.seconds*1000;waitingForAudio=m.phase==='question';}intent='attack';lastTick=Date.now();renderBattle();clearInterval(timerId);timerId=setInterval(tick,120);if(m.phase==='question'&&(!same||newWord)&&!paused)speak(round.card.english,{first:true});}
function enemySpecies(){return species(state.mission.enemy.instance.speciesId);}
function currentMonster(){return indexOf(state.mission.enemy.instance.speciesId);}
function hpBar(value,max,label,cls=''){return `<div class="hp-line"><span>${label}</span><div class="hp-track ${cls}" role="progressbar" aria-label="${label}" aria-valuemin="0" aria-valuemax="${max}" aria-valuenow="${value}"><div class="hp-fill" style="width:${Math.max(0,value/max*100)}%"></div></div><small>${value}/${max}</small></div>`;}
function renderBattle(){stopPark();view='game';const m=state.mission,p=state.profile,e=enemySpecies(),ally=p.inventory.find(x=>x.id===m.active),a=species(ally.speciesId),stats=monsterStats(ally,MONSTERS),v=m.vitals[ally.id];sound.setScene(m.enemy.boss?'boss':'field');app.innerHTML=`${header(true)}<main class="game-page"><div class="adventure-toolbar"><div class="journey-info"><strong>${m.enemy.boss?'Guardian Battle':'Frontier Ridge Mission'}</strong><span> / ${esc(courseName())}</span></div><div class="journey-path">${Array.from({length:6},(_,i)=>`<span class="path-node ${i<m.stage?'complete':i===m.stage?'current':''}">${i<m.stage?'✓':i===5?'★':i+1}</span>`).join('')}</div></div><section class="arena rpg-arena ${m.enemy.boss?'boss':''}" aria-label="Monster battle arena"><span class="location-label">${icon('leaf')}FRONTIER RIDGE · ${m.enemy.boss?'GUARDIAN ZONE':'ENCOUNTER'}</span><div class="monster-status"><div class="monster-name"><strong>${e.name}</strong>${badge(e)}</div><small>${m.enemy.boss?'BOSS · ':''}${e.type} · Lv.${m.enemy.instance.level}</small>${hpBar(m.enemy.hp,m.enemy.maxHp,'Enemy HP')}<div class="hp-count">${canCatch(m)?'CATCH RANGE · Answer a word to try!':'Weaken to 35% HP to catch'}</div></div><div class="encounter-bubble" id="encounter-bubble">${esc(m.result?.message||`${e.name} appeared! Hear the word and choose your move.`)}</div><div class="enemy-wrap ${m.enemy.boss?'boss-enemy':''} ${m.result?.captured?'captured':''}" id="enemy-wrap"><div class="enemy-shadow"></div>${sprite(currentMonster(),'enemy')}<span class="enemy-word ${m.phase==='question'?'':'revealed'}" id="enemy-word">${m.phase==='question'?'? '.repeat(Math.min(round.card.english.length,8)):esc(round.card.english)}</span></div><div class="ally-wrap" id="ally-wrap">${sprite(indexOf(a.id),'ally-monster')}</div><div class="hero-actor rpg-ranger" id="hero-actor"><img class="arena-player" src="assets/ranger-v3.png" alt="Original ranger with a Wordlink laptop"><div class="hero-action-sprite" aria-hidden="true"></div></div><div class="action-caption" role="status" aria-live="polite"></div><div class="player-status rpg-player-status"><strong>${a.name} <small>Lv.${ally.level} · ${a.type}</small></strong>${hpBar(v.hp,stats.hp,'Team HP')}${hpBar(v.mp,stats.mp,'MP','mp-track')}</div><div class="timer-badge" id="timer-badge">${icon(m.settings.timed?'clock':'leaf')}<span id="time-left">${m.settings.timed?Math.ceil(remainingMs/1000)+'s':'∞ No timer'}</span></div>${paused?pauseMarkup():''}</section><section class="computer-shell"><div class="computer-top"><span class="led"></span>WORDLINK · BATTLE TERMINAL</div><div class="move-picker" aria-label="Choose a battle action">${[['attack','Attack',a.type==='WIND'?'Recharge 6 MP':'Recharge 4 MP'],['special',a.specialMove,`${specialCost(a)} MP`],['catch','Catch',`${Math.round(CATCH_RATES[e.rarity]*100)}% when weakened`]].map(([id,label,note])=>`<button data-action="intent" data-value="${id}" class="move-button ${intent===id?'selected':''}" aria-pressed="${intent===id}" ${m.phase!=='question'||id==='catch'&&!canCatch(m)||id==='special'&&v.mp<specialCost(a)?'disabled':''}><strong>${label}</strong><small>${note}</small></button>`).join('')}</div><div class="computer-screen" id="computer-screen">${m.phase==='question'?questionMarkup():resultMarkup()}</div></section><div class="battle-team"><strong>Switch teammate</strong>${p.team.map(id=>{const inst=p.inventory.find(x=>x.id===id),s=species(inst.speciesId);return `<button data-action="switch" data-id="${id}" class="${id===m.active?'selected':''}" ${m.phase!=='question'||!m.vitals[id].hp?'disabled':''}>${sprite(indexOf(s.id))}<span>${s.name}<small>HP ${m.vitals[id].hp}</small></span></button>`;}).join('')}</div><div class="game-bottom"><div class="game-stats"><span>Caught <b>${m.captures.length}</b></span><span><b>${m.score}</b> pts</span><span>${round.mode==='spell'?'Spell It':'Listen & Pick'}</span><span>${guest?'Local save':'Cloud save'}</span></div><span class="keyboard-note">Space: listen · 1–4: choose · Esc: pause</span></div></main>`;}
function questionMarkup(){return `<div class="question-top"><div class="question-label"><button class="audio-button" data-action="replay" aria-label="Listen again">${icon('sound')}</button><div><strong>${round.mode==='choice'?'Which word did you hear?':'Spell the word you hear!'}</strong><small>${round.mode==='choice'?'Choose the word to power your move.':'Tap each letter in order, including any hyphen.'}</small></div></div><button class="help-button" data-action="hint">Word hint</button></div>${round.mode==='choice'?`<div class="choice-grid">${round.options.map((word,i)=>`<button class="answer-choice" data-action="answer" data-word="${esc(word)}"><span class="key">${i+1}</span>${esc(word)}</button>`).join('')}</div>`:spellMarkup()}<div class="feedback" id="feedback" role="status">${esc(round.message)}</div>`;}
function spellMarkup(){return `<div class="spell-slots" aria-label="Your letter order">${[...round.card.english].map((_,i)=>round.selected[i]!==undefined?`<button class="letter-slot filled" data-action="unletter" data-index="${i}" aria-label="Remove letter in slot ${i+1}">${esc(round.letters.find(t=>t.id===round.selected[i]).letter)}</button>`:`<span class="letter-slot" aria-label="Empty slot ${i+1}"></span>`).join('')}</div><div class="letter-bank">${round.letters.map(t=>`<button class="letter-tile" data-action="letter" data-id="${t.id}" aria-label="Choose letter ${t.letter}" ${round.selected.includes(t.id)?'disabled':''}>${esc(t.letter)}</button>`).join('')}</div><div class="spell-tools"><button data-action="backspace">Undo</button><button data-action="clear-letters">Clear letters</button></div>`;}
function updateQuestion(){if($('#computer-screen'))$('#computer-screen').innerHTML=questionMarkup();if(speaking)$('.audio-button')?.classList.add('speaking');}
function resultMarkup(){const r=state.mission.result;return `<div class="result-row" role="status"><div><div class="eyebrow">${r.captured?'NEW TEAMMATE!':r.correct?'WORD LINK COMPLETE':'KEEP TRAINING!'}</div><div class="result-word">${esc(round.card.english)}<small>${esc(round.card.pos_zh)} · ${esc(round.card.meaning_zh)}</small></div><p>${esc(r.message)} ${r.points?'+'+r.points+' pts':''}</p></div><div class="result-actions">${r.captured?'<button class="secondary-button" data-action="recruit">Send to battle</button>':''}<button class="audio-button" data-action="speak-word" data-word="${esc(round.card.english)}" aria-label="Hear the answer">${icon('sound')}</button><button class="next-button" data-action="next">${r.rescued?'Return to base':r.finishedEncounter?'Next encounter':'Next word'}${icon('arrow')}</button></div></div>`;}
async function submitAnswer(answer,{timeout=false}={}){if(actionBusy||networkBusy||view!=='game'||round?.phase!=='question'||paused||modal.open)return;const qid=round.id,assisted=round.assisted;stopSpeech();waitingForAudio=false;lockBattleControls(true);try{await act({type:'answer',questionId:qid,intent,answer,hint:assisted,timeout});round.phase='result';round.result=state.mission.result;renderBattle();await runBattleAction(round.result.correct?(round.result.captured?'capture':round.result.intent==='catch'?'miss':'hit'):'wrong',currentMonster());}catch(e){toast(e.message);round.selected=[];updateQuestion();lastTick=Date.now();if(remainingMs===0)pause();if(e.status===409)syncRound(true);}finally{lockBattleControls(false);}}
function lockBattleControls(value){$('#computer-screen')?.setAttribute('aria-busy',String(value));document.querySelectorAll('#computer-screen button,.move-picker button,.battle-team button').forEach(b=>{if(value){if(!b.disabled){b.dataset.actionLocked='true';b.disabled=true;}}else if(b.dataset.actionLocked){delete b.dataset.actionLocked;b.disabled=false;}});}
function stopBattleAction(){if(battleAction){battleAction.cancel();battleAction=null;}actionBusy=false;lockBattleControls(false);}
async function runBattleAction(kind,index){stopBattleAction();stopSpeech();actionBusy=true;lockBattleControls(true);const action=battleAction=new BattleAction($('.arena'),sound,speaker),r=state.mission.result;try{await action.play(kind,index,state.mission.stage===5&&r.finishedEncounter,{damage:r.damage,counterDamage:r.counterDamage,move:r.intent==='special'?species(state.profile.inventory.find(m=>m.id===state.mission.active).speciesId).specialMove:'TEAM ATTACK!',enemyMove:r.enemySpecial?enemySpecies().specialMove:enemySpecies().type+' STRIKE'});}catch{toast('Ready for your next word.');}if(battleAction!==action)return;action.clean();battleAction=null;actionBusy=false;lockBattleControls(false);lastTick=Date.now();}
async function nextRound(){if(actionBusy||networkBusy||paused)return;stopBattleAction();stopSpeech();await act({type:'next'});syncRound(true);}
function chooseLetter(id){if(actionBusy||networkBusy||paused||round?.phase!=='question'||round.mode!=='spell'||round.selected.includes(id))return;sfx('letter');round.selected.push(id);round.message='';updateQuestion();if(round.selected.length===round.letters.length)submitAnswer(round.selected.map(id=>round.letters.find(t=>t.id===id).letter).join(''));}
function tick(){const now=Date.now(),dt=now-lastTick;lastTick=now;if(view!=='game'||round?.phase!=='question'||paused||actionBusy||networkBusy||modal.open||waitingForAudio||!state.mission.settings.timed)return;remainingMs=Math.max(0,remainingMs-dt);if($('#time-left'))$('#time-left').textContent=Math.ceil(remainingMs/1000)+'s';$('#timer-badge')?.classList.toggle('urgent',remainingMs<6000);if(!remainingMs)submitAnswer('',{timeout:true});}
function pauseMarkup(){return `<div class="pause-cover"><h2>Mission paused</h2><p>Your team is waiting for you.</p><button class="next-button" data-action="resume">Resume mission</button><button class="help-button" data-action="confirm-home">Return to base</button></div>`;}
function pause(){if(view!=='game'||paused)return;stopBattleAction();stopSpeech();paused=true;$('.arena')?.insertAdjacentHTML('beforeend',pauseMarkup());}
function resume(){paused=false;$('.pause-cover')?.remove();lastTick=Date.now();if(waitingForAudio&&round.phase==='question')speak(round.card.english,{first:true});}
function confirmHome(){if(view!=='game')return renderHome();pause();openModal(modalHeading('Return to base?','Caught teammates and earned XP stay saved. This mission will end.')+`<div class="finish-actions"><button class="secondary-button" data-action="close-modal">Keep playing</button><button class="next-button" data-action="leave-game">Return to base</button></div>`);}
function renderFinish(){stopPark();stopSpeech();clearInterval(timerId);view='finish';const m=state.mission,cleared=m.phase==='complete';sound.setScene('home');app.innerHTML=`${header()}<main class="finish-page"><div class="finish-eyebrow">${cleared?'MISSION COMPLETE':'RESCUE COMPLETE'}</div><h1>${cleared?'Great work, ranger!':'Your team is safe.'}</h1><p>${cleared?'Keep learning. Your next teammate is out there.':'Rest up at base. Your caught monsters and XP are saved.'}</p><div class="finish-monsters">${m.captures.map(id=>sprite(indexOf(state.profile.inventory.find(x=>x.id===id).speciesId))).join('')||sprite(currentMonster())}</div><div class="records-summary"><div class="record-number"><strong>${m.score}</strong>Points</div><div class="record-number"><strong>${m.captures.length}</strong>Caught</div><div class="record-number"><strong>${Math.round(m.correct/Math.max(1,m.attempts)*100)}%</strong>Accuracy</div></div><div class="finish-actions"><button class="secondary-button" data-action="warehouse">Choose your battle team</button><button class="secondary-button" data-action="park">Visit Team Park</button><button class="next-button" data-action="home">Return to base</button></div></main>`;}

function statsMarkup(inst){const stats=monsterStats(inst,MONSTERS);return `<dl class="stat-grid">${STAT_KEYS.map(k=>`<div><dt>${k.toUpperCase()}</dt><dd>${stats[k]}<small>IV ${inst.iv[k]}/31</small></dd></div>`).join('')}</dl><small>Quality ${quality(inst)}% · Lv.${inst.level} · XP ${inst.xp}/${inst.level*35} · Individual values affect stats</small>`;}
function showWarehouse(){if(!state.profile)return toast('Choose your first teammate.');const p=state.profile,filtered=p.inventory.filter(x=>warehouseFilter==='All'||species(x.speciesId).rarity===warehouseFilter).toSorted((a,b)=>RARITIES.indexOf(species(b.speciesId).rarity)-RARITIES.indexOf(species(a.speciesId).rarity)||b.level-a.level),pages=Math.max(1,Math.ceil(filtered.length/12));warehousePage=Math.min(warehousePage,pages-1);const active=state.mission&&['question','result'].includes(state.mission.phase);openModal(modalHeading('Monster warehouse',`${p.inventory.length} teammates · Team ${p.team.length}/3 · Select up to 3 for battle`)+`<div class="warehouse-toolbar"><select id="rarity-filter" aria-label="Filter by rarity">${['All',...RARITIES].map(r=>`<option ${warehouseFilter===r?'selected':''}>${r}</option>`).join('')}</select><button class="secondary-button" data-action="collection">100-species field guide</button></div>${active?'<p>Return to base to reorganize your team. Newly caught teammates can join immediately from the battle result.</p>':''}<div class="warehouse-grid">${filtered.slice(warehousePage*12,warehousePage*12+12).map(inst=>{const m=species(inst.speciesId),on=p.team.includes(inst.id);return `<article class="warehouse-card ${on?'on-team':''}"><div class="warehouse-card-top">${badge(m)}<small>#${String(m.dex).padStart(3,'0')}</small></div>${sprite(indexOf(m.id))}<h3>${esc(m.name)} <small>${m.type}</small></h3>${statsMarkup(inst)}<div class="ability"><strong>${esc(m.ability.name)}</strong><p>${esc(m.ability.description)}</p><small>Special: ${esc(m.specialMove)} · ${specialCost(m)} MP</small></div><button class="secondary-button" data-action="team-toggle" data-id="${inst.id}" ${active||on&&p.team.length===1||!on&&p.team.length===3?'disabled':''}>${on?'✓ On team · Remove':'Add to battle team'}</button><small class="caught-date">${inst.origin==='starter'?'Starter gift':inst.origin==='legacy'?'Previous local collection':'Caught '+new Date(inst.caughtAt).toLocaleDateString('en-US')}</small></article>`;}).join('')||'<p>No teammates match this rarity yet.</p>'}</div><div class="pagination"><button data-action="warehouse-prev" ${warehousePage===0?'disabled':''}>Previous</button><span>${warehousePage+1} / ${pages}</span><button data-action="warehouse-next" ${warehousePage>=pages-1?'disabled':''}>Next</button></div>`);}
function showCollection(){const p=state.profile;if(!p)return toast('Choose your starter first.');const owned=new Set(p.inventory.map(x=>x.speciesId)),odds=encounterOdds(p.adventures,settings.mode);openModal(modalHeading('100-species field guide',`${owned.size}/100 species owned · ${p.adventures} missions cleared`)+`<div class="rarity-guide">${RARITIES.map(r=>`<div>${badge({rarity:r})}<span>${p.adventures<UNLOCKS[r]?'Unlock: '+UNLOCKS[r]+' cleared missions':(odds[r]*100).toFixed(2)+'% encounter chance'}</span><small>Catch: ${Math.round(CATCH_RATES[r]*100)}% per correct attempt</small></div>`).join('')}</div><p>Spell It gives Rare, Epic, and Legendary encounter weights a 15% boost. Unlocks and catch rates stay the same. A monster can escape after 3 failed catches.</p><div class="collection-grid full-dex">${MONSTERS.map((m,i)=>`<article class="collection-card ${owned.has(m.id)?'':'locked'}"><span class="caught-mark">${owned.has(m.id)?'✓ Owned':'Not caught'}</span>${sprite(i)}<small>#${String(m.dex).padStart(3,'0')} · ${m.type}</small><h3>${m.name}</h3>${badge(m)}<p>${m.description}</p></article>`).join('')}</div>`);}
async function showLeaderboard(){openModal(modalHeading('Ranger leaderboard','Loading the ranger network…')+'<p role="status">Fetching real player collections…</p>');try{const result=await cloud.leaderboard();if(!modal.open)return;modal.innerHTML=modalHeading('Ranger leaderboard',`${result.players} registered players · Top 100 collections`)+`<p>Ranked by rarity points, then unique species and caught totals. Starter gifts do not add caught totals or rarity points.</p><p class="ranking-key">Common 1 · Uncommon 3 · Rare 10 · Epic 35 · Legendary 150 points</p><div class="leaderboard-scroll"><table class="leaderboard"><thead><tr><th>Rank</th><th>Player</th><th>Caught</th><th>Species</th><th>Common</th><th>Uncommon</th><th>Rare</th><th>Epic</th><th>Legendary</th><th>Points</th></tr></thead><tbody>${result.rows.map((r,i)=>`<tr class="${r.alias===alias?'you':''}"><td>${i+1}</td><th scope="row">${esc(r.alias)}</th><td>${r.caught}</td><td>${r.unique_species}/100</td>${RARITIES.map(k=>`<td>${r.rarity_counts[k]||0}</td>`).join('')}<td>${r.rarity_points}</td></tr>`).join('')||'<tr><td colspan="10">No players yet. Create your ranger code to join!</td></tr>'}</tbody></table></div><p>${guest?'Guest collections stay on this device and are not ranked.':'Your collection updates after each saved move.'}</p><button class="secondary-button" data-action="leaderboard">Refresh</button>`;}catch(e){modal.innerHTML=modalHeading('Ranger leaderboard')+`<p>${esc(e.message)}</p><button class="secondary-button" data-action="leaderboard">Try again</button>`;}}
function parkDetail(index){const m=MONSTERS[index],instances=state.profile.inventory.filter(x=>x.speciesId===m.id),best=instances.toSorted((a,b)=>b.level-a.level)[0];return `${sprite(index,'park-detail-sprite')}<div>${badge(m)}<h2>${m.name}<span>${instances.length} owned · Best Lv.${best.level}</span></h2><p>${m.description}</p><small>${m.ability.name}: ${m.ability.description}</small><button class="text-button" data-action="warehouse">View stats & choose team</button></div>`;}
function showPark(refresh=false){if(!state.profile)return toast('Choose your starter first.');if(view!=='park'){parkReturnView=view;parkWasPaused=paused;}else if(!refresh)return;stopBattleAction();if(view==='game')paused=true;stopSpeech();stopPark();view='park';sound.setScene('park');const owned=MONSTERS.map((m,index)=>({...m,index})).filter(m=>state.profile.inventory.some(x=>x.speciesId===m.id)),pages=Math.max(1,Math.ceil(owned.length/12));parkPage=Math.min(parkPage,pages-1);const residents=owned.slice(parkPage*12,parkPage*12+12);app.innerHTML=`${header()}<main class="park-page"><div class="park-heading"><div><div class="eyebrow">YOUR TEAM. YOUR NEXT MISSION.</div><h1>Your <span>Team Park</span></h1><p>Watch your teammates roam. Tap one to say hello.</p></div><button class="secondary-button" data-action="park-back">Back to ${parkReturnView==='game'?'battle':'base'}</button></div><div class="park-toolbar"><div class="park-count"><strong>${owned.length}/100</strong> species owned</div><div class="park-actions"><button data-action="park-gather">Rally</button><button data-action="park-feed">Snack time</button><button data-action="warehouse">Warehouse</button></div></div><section class="park-world" id="park-world" aria-label="Park with freely roaming caught monsters"><div class="park-sign">TEAM PARK<small>FRONTIER RANGERS</small></div><div class="park-weather">☀ Clear skies</div><div class="park-picnic" aria-hidden="true"><span>✦</span><i></i><i></i><i></i></div>${residents.map(m=>`<button class="park-creature" data-action="pet-monster" data-park-id="${m.id}" aria-label="Greet ${m.name}"><span class="park-shadow"></span><span class="park-face">${sprite(m.index,'park-sprite')}</span><span class="park-monster-name">${m.name}</span><span class="park-heart">✦</span></button>`).join('')}<div class="park-activity" id="park-activity" role="status">Your team is on patrol.</div></section><div class="park-bottom"><section class="park-detail" id="park-detail">${residents.length?parkDetail(residents[0].index):''}</section></div><div class="pagination"><button data-action="park-prev" ${parkPage===0?'disabled':''}>Previous area</button><span>Area ${parkPage+1}/${pages} · Up to 12 residents</span><button data-action="park-next" ${parkPage>=pages-1?'disabled':''}>Next area</button></div></main>`;park=new MonsterPark($('#park-world'),residents,{onPet:c=>{sound.cry(c.index);speak('@pet');$('#park-detail').innerHTML=parkDetail(c.index);$('#park-activity').textContent=`${MONSTERS[c.index].name} says hello!`;}});}
function backFromPark(){stopPark();stopSpeech();if(parkReturnView==='game'&&state.mission){paused=parkWasPaused;renderBattle();lastTick=Date.now();if(waitingForAudio&&!paused&&round.phase==='question')speak(round.card.english,{first:true});}else renderHome();}
function showRecords(){const p=state.profile,words=Object.keys(p.words).sort();openModal(modalHeading('Mission records',guest?'Saved on this device':'Synced to your player code')+`<div class="records-summary"><div class="record-number"><strong>${words.filter(w=>p.words[w].correct>0).length}</strong>Words practiced</div><div class="record-number"><strong>${p.adventures}</strong>Missions cleared</div><div class="record-number"><strong>${p.bestScore}</strong>Best score</div></div><div class="word-records">${words.map(w=>`<span>${esc(w)} <small>✓ ${p.words[w].correct}/${p.words[w].attempts}</small></span>`).join('')||'<p>Your first word starts here.</p>'}</div>`);}
function help(){openModal(modalHeading('Ranger field guide')+`<div class="help-content"><h3>Choose your words</h3><p>Select CET Weeks, FET Lessons, a whole course, or everything together. Choose Listen & Pick, Spell It, or Mixed. Use no timer, or 15, 25, or 40 seconds per word.</p><h3>Listen and battle</h3><p>Choose Attack, your special move, or Catch. Hear the word, then pick an answer or arrange its letters. Correct words power your move. Wrong answers and timeouts let the wild monster attack. Basic attacks restore MP; special moves use MP.</p><h3>Catch your teammates</h3><p>Lower the wild monster to 35% HP, choose Catch, and answer correctly for a catch attempt. Rarer monsters are harder to catch. After three failed catches, they escape. Your caught monster can join the battle right away: tap Send to battle.</p><h3>Guardian missions</h3><p>Face five ordinary encounters, then a guardian with more HP that needs at least three successful attacks. Finish all six encounters to clear a mission. If your whole team faints, everyone returns safely to base. Caught monsters and XP stay saved.</p><h3>100 original monsters</h3><p>Uncommon unlocks after 2 cleared missions, Rare after 8, Epic after 30, and Legendary after 80. Unlocking allows a rare encounter; it never guarantees one. Spell It boosts high-rarity encounter weights by 15%, with the same catch difficulty.</p><h3>Warehouse and Team Park</h3><p>Each monster has its own level, XP, individual values, and HP, MP, Attack, Defense, and Special stats. Build a team of up to three at base. Your owned species roam in park areas of up to 12 residents.</p><h3>Voice and saving</h3><p>Jenny reads every word in natural American English. Music falls silent during speech. Online player saves sync across devices. Guest saves stay on this device and do not appear on the leaderboard. The practice timer pauses during voice, actions, settings, and breaks.</p></div>`);}
function showAccount(){openModal(modalHeading(guest?'Guest ranger':alias,guest?'Local save · not on the leaderboard':'Cloud player · saved across devices')+`<div class="finish-actions"><button class="secondary-button" data-action="records">Word records</button><button class="secondary-button" data-action="collection">Field guide</button><button class="secondary-button" data-action="logout">${guest?'Back to sign in':'Sign out'}</button></div><p>${guest?'Your guest progress will remain on this device.':'Keep your password and recovery code safe. Only your ranger code and collection totals are public.'}</p>`);}
function recover(){openModal(modalHeading('Recover your ranger account','Use the recovery code saved when you created your player.')+`<form id="recover-form"><label>Player code<input name="alias" required autocapitalize="none" autocomplete="username"></label><label>Recovery code<input name="recovery" required autocapitalize="none" spellcheck="false" minlength="32" maxlength="40"></label><label>New password<input type="password" name="password" required minlength="8" maxlength="64" autocomplete="new-password"></label><p id="recover-feedback" role="status"></p><button class="next-button">Reset password</button></form>`);}
async function dispatch(action,target){if((actionBusy||networkBusy)&&['answer','letter','unletter','backspace','clear-letters','replay','hint','next','intent','switch','recruit'].includes(action))return;switch(action){
 case 'auth-mode':renderAuth(target.dataset.mode);break;
 case 'guest':{guest=true;alias='';state=read('wordling-guest-v2',null)||{profile:null,mission:null};const legacy=read('wordling-progress-v1',null);if(!state.profile&&Object.keys(legacy?.captured||{}).length)state.profile=migrateLegacy(legacy,MONSTERS);save();enterProfile();break;}
 case 'starter':await act({type:'starter',speciesId:target.dataset.id});renderHome();break;
 case 'recovery-done':modal.close();enterProfile();break;
 case 'recover':recover();break;
 case 'mode':settings.mode=target.dataset.value;save();renderHome();break;
 case 'timed':settings.timed=target.dataset.value==='true';save();renderHome();break;
 case 'course':settings.course=target.dataset.value;settings.scope='all';settings.groupIds=[];save();renderHome();break;
 case 'unit':{const id=target.dataset.value;if(settings.scope==='all'){settings.groupIds=[];settings.scope='custom';}settings.groupIds=settings.groupIds.includes(id)?settings.groupIds.filter(n=>n!==id):[...settings.groupIds,id];save();renderHome();break;}
 case 'course-all':settings.scope='custom';settings.groupIds=data.groups.filter(g=>g.course===target.dataset.course).map(g=>g.id);save();renderHome();break;
 case 'all-units':settings.scope='all';settings.groupIds=[];save();renderHome();break;
 case 'clear-units':settings.scope='custom';settings.groupIds=[];save();renderHome();break;
 case 'start':await startGame();break;
 case 'resume-mission':paused=false;syncRound(true);break;
 case 'answer':await submitAnswer(target.dataset.word);break;
 case 'letter':chooseLetter(Number(target.dataset.id));break;
 case 'unletter':if(round?.phase==='question'&&!paused){round.selected.splice(Number(target.dataset.index),1);updateQuestion();}break;
 case 'backspace':if(round?.phase==='question'&&!paused){round.selected.pop();updateQuestion();}break;
 case 'clear-letters':if(round?.phase==='question'&&!paused){round.selected=[];updateQuestion();}break;
 case 'intent':intent=target.dataset.value;document.querySelectorAll('.move-button').forEach(b=>{b.classList.toggle('selected',b.dataset.value===intent);b.setAttribute('aria-pressed',b.dataset.value===intent);});break;
 case 'switch':await act({type:'switch',id:target.dataset.id});renderBattle();break;
 case 'recruit':await act({type:'recruit',id:state.mission.captures.at(-1)});renderBattle();toast('Your new teammate is ready for the next encounter!');break;
 case 'replay':if(!paused)speak(round.card.english,{first:waitingForAudio});break;
 case 'speak-word':speak(target.dataset.word);break;
 case 'hint':if(round?.phase==='question'&&!paused){round.assisted=true;round.message=`Hint: ${round.card.english} — ${round.card.meaning_zh}`;$('#enemy-word').textContent=round.card.english;$('#enemy-word').classList.add('revealed');updateQuestion();}break;
 case 'next':await nextRound();break;
 case 'pause':pause();break;
 case 'resume':resume();break;
 case 'home':if(!state.profile){renderAuth();break;}if(view==='game')confirmHome();else if(view==='park'&&parkReturnView==='game'){backFromPark();confirmHome();}else{stopBattleAction();stopSpeech();renderHome();}break;
 case 'confirm-home':confirmHome();break;
 case 'leave-game':await act({type:'leave'});modalPaused=false;modal.close();clearInterval(timerId);stopSpeech();paused=false;round=null;renderHome();break;
 case 'park':showPark();break;
 case 'park-back':backFromPark();break;
 case 'park-prev':parkPage--;showPark(true);break;
 case 'park-next':parkPage++;showPark(true);break;
 case 'park-gather':park?.gather();sfx('start');$('#park-activity').textContent='Rally up!';break;
 case 'park-feed':park?.feed();sfx('feed');$('#park-activity').textContent='Snack time!';break;
 case 'pet-monster':park?.pet(target.dataset.parkId);break;
 case 'warehouse':showWarehouse();break;
 case 'warehouse-prev':warehousePage--;showWarehouse();break;
 case 'warehouse-next':warehousePage++;showWarehouse();break;
 case 'team-toggle':{const p=state.profile,ids=p.team.includes(target.dataset.id)?p.team.filter(id=>id!==target.dataset.id):[...p.team,target.dataset.id];await act({type:'team',ids});showWarehouse();break;}
 case 'collection':showCollection();break;
 case 'leaderboard':await showLeaderboard();break;
 case 'records':showRecords();break;
 case 'account':showAccount();break;
 case 'logout':stopBattleAction();stopPark();stopSpeech();clearInterval(timerId);if(!guest)await cloud.logout();guest=false;state={profile:null,mission:null};alias='';modalPaused=false;modal.close();renderAuth();break;
 case 'sound-settings':showSoundSettings();break;
 case 'preview-voice':speak('flower');break;
 case 'toggle-audio':{const key=target.dataset.setting;settings[key]=!settings[key];sound.activate();sound.update();save();target.classList.toggle('on',settings[key]);target.setAttribute('aria-pressed',settings[key]);target.textContent=settings[key]?'On':'Off';break;}
 case 'help':help();break;
 case 'close-modal':stopSpeech();modal.close();break;
}}
document.addEventListener('pointerdown',()=>sound.activate(),{once:true});
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target||target.disabled||modal.open&&!modal.contains(target))return;dispatch(target.dataset.action,target).catch(e=>toast(e.message));});
document.addEventListener('submit',e=>{if(e.target.id==='account-form'){e.preventDefault();loginForm(e.target);}if(e.target.id==='recover-form'){e.preventDefault();const f=e.target,v=new FormData(f),b=f.querySelector('button');b.disabled=true;cloud.request('recover',{alias:v.get('alias'),password:v.get('password'),recoveryCode:v.get('recovery')}).then(r=>{modal.innerHTML=modalHeading('Password reset','Save this new recovery code. The old code no longer works.')+`<code class="recovery-code">${r.recoveryCode}</code><button class="next-button" data-action="close-modal">Saved · Sign in</button>`;}).catch(e=>{$('#recover-feedback').textContent=e.message;b.disabled=false;});}});
document.addEventListener('input',e=>{const key=e.target.dataset.volume;if(!key)return;settings[key]=Number(e.target.value)/100;sound.update();save();$('#'+key+'-value').textContent=e.target.value+'%';});
document.addEventListener('change',e=>{if(e.target.id==='seconds'){settings.seconds=Number(e.target.value);save();}if(e.target.id==='rarity-filter'){warehouseFilter=e.target.value;warehousePage=0;showWarehouse();}});
modal.addEventListener('close',()=>{stopSpeech();if(modalPaused&&view==='game'){paused=false;lastTick=Date.now();if(waitingForAudio&&round?.phase==='question')speak(round.card.english,{first:true});}modalPaused=false;});
document.addEventListener('keydown',e=>{if(view!=='game'||modal.open||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='Escape'){e.preventDefault();paused?resume():pause();return;}if(paused||actionBusy||networkBusy)return;if(e.code==='Space'){e.preventDefault();if(round.phase==='question')speak(round.card.english,{first:waitingForAudio});return;}if(round.phase!=='question'){if(e.key==='Enter'){e.preventDefault();nextRound().catch(e=>toast(e.message));}return;}if(round.mode==='choice'&&/^[1-4]$/.test(e.key)){e.preventDefault();submitAnswer(round.options[Number(e.key)-1]);}else if(round.mode==='spell'){if(e.key==='Backspace'){e.preventDefault();round.selected.pop();updateQuestion();}else if(/^[a-zA-Z-]$/.test(e.key)){e.preventDefault();const tile=round.letters.find(t=>t.letter===e.key.toLowerCase()&&!round.selected.includes(t.id));if(tile)chooseLetter(tile.id);}}});
document.addEventListener('visibilitychange',()=>{sound.setVisible(!document.hidden);if(document.hidden){stopSpeech();if(view==='game'&&!modal.open)pause();}});
try{const responses=await Promise.all(['data/vocabulary.json','data/monsters.json','config.json'].map(p=>fetch(p)));if(responses.some(r=>!r.ok))throw Error('Game files could not load.');[data,MONSTERS]=await Promise.all(responses.slice(0,2).map(r=>r.json()));cloud=new RangerCloud(await responses[2].json());settings.groupIds=Array.isArray(settings.groupIds)?settings.groupIds.filter(id=>data.groups.some(g=>g.id===id)):[];if(!['ALL','CET','FET'].includes(settings.course))settings.course='ALL';if(!['choice','spell','mixed'].includes(settings.mode))settings.mode='mixed';if(![15,25,40].includes(settings.seconds))settings.seconds=25;if(!['all','custom'].includes(settings.scope))settings.scope='all';renderAuth();if(cloud.session){try{const r=await cloud.me();state=r.state;alias=r.alias;enterProfile();}catch(e){renderAuth('login',e.message);}}}catch(e){app.innerHTML=`<main class="error-box"><h1>The island is loading</h1><p>${esc(e.message)}</p><button onclick="location.reload()" class="next-button">Reload</button></main>`;}
